        "ai_agent_card1_body" to mapOf(
            "ar" to "📉 مقارنة السوق اليومية: مخزون العلف الحالي (7.5 ق) يكفي ليومين فقط. وجدتُ لك في السوق عرض علف عند (كمال - البليدة) يوفر عليك 18,000 دج مقارنة بآخر فاتورة. هل أجهز لك طلبية التوريد وأرسلها للمورد؟",
            "fr" to "📉 Comparaison du marché : Le stock d'aliment actuel (7.5 q) suffit pour 2 jours. J'ai trouvé une offre chez (Kamal - Blida) qui vous économise 18 000 DZD par rapport à la dernière facture. Préparer et envoyer la commande ?",
            "en" to "📉 Daily Market Comparison: Current feed stock (7.5 q) lasts only 2 days. I found a bulk feed offer from (Kamal - Blida) saving you 18,000 DZD vs. your last invoice. Shall I prepare and send the supply order?",
            "es" to "📉 Comparación del mercado: El stock de alimento actual (7.5 q) dura solo 2 días. Encontré una oferta en (Kamal - Blida) que le ahorra 18,000 DZD respecto a la última factura. ¿Preparo y envío el pedido?",
            "pt" to "📉 Comparação de mercado: O estoque atual de ração (7.5 q) dura apenas 2 dias. Encontrei uma oferta em (Kamal - Blida) que economiza 18.000 DZD em relação à última fatura. Posso preparar e enviar o pedido?",
            "hi" to "📉 बाजार तुलना: वर्तमान चारा स्टॉक (7.5 q) केवल 2 दिनों के लिए पर्याप्त है। मुझे (कमाल - ब्लिडा) के पास एक ऑफर मिला है जो पिछले बिल की तुलना में 18,000 बचाता है। क्या मैं आपूर्ति ऑर्डर भेज दूँ?",
            "tr" to "📉 Günlük Piyasa Karşılaştırması: Mevcut yem stoğu (7.5 kental) yalnızca 2 gün yeter. Piyasada (Kemal - Blida) son faturanıza göre 18.000 tasarruf sağlayan bir teklif buldum. Siparişi hazırlayıp göndereyim mi?",
            "id" to "📉 Perbandingan Pasar: Stok pakan saat ini (7.5 kuintal) hanya cukup 2 hari. Saya menemukan penawaran di (Kamal - Blida) yang menghemat 18.000 dibanding faktur terakhir. Siapkan dan kirim pesanan sekarang?",
            "ur" to "📉 مارکیٹ موازنہ: موجودہ فیڈ اسٹاک (7.5 قنطار) صرف 2 دن کے لیے کافی ہے۔ مجھے مارکیٹ میں (کمال - البليدة) کے پاس پیشکش ملی ہے جو پچھلے بل کے مقابلے میں 18,000 دج بچاتی ہے۔ کیا میں آرڈر تیار کر کے بھیج دوں؟",
            "sw" to "📉 Ulinganisho wa Soko: Akiba ya chakula (7.5 q) inatosha siku 2 pekee. Nimepata ofa kwa (Kamal - Blida) inayookoa 18,000 ikilinganishwa na ankara iliyopita. Niandae na kutuma oda sasa?",
            "ru" to "📉 Сравнение рынка: Текущего запаса корма (7.5 ц) хватит только на 2 дня. Найдено предложение у (Камаль - Блида) с экономией 18 000 по сравнению с прошлым счетом. Подготовить и отправить заказ?",
            "zh" to "📉 每日市场比价：当前饲料库存 (7.5 公担) 仅够维持 2 天。我在市场发现 (卡马尔 - 布利达) 的报价较上次发票为您节省 18,000。是否立即生成并发送采购单？",
            "de" to "📉 Marktvergleich: Der aktuelle Futterbestand (7,5 q) reicht nur für 2 Tage. Ich habe ein Angebot bei (Kamal - Blida) gefunden, das 18.000 gegenüber der letzten Rechnung spart. Bestellung vorbereiten und senden?",
