            "hi" to "⏰ स्मार्ट अलर्ट: अगले टीकाकरण / आवधिक बिल की तिथि नजदीक है, और शेड का तापमान स्थिर (23.0°C) है। क्या मैं पानी की लाइनें तैयार करने के लिए सुपरवाइजर को तुरंत रिमाइंडर भेजूं?",
            "tr" to "⏰ Proaktif Uyarı: Yaklaşan aşılama / dönemlik fatura tarihi yaklaştı ve kümes sıcaklığı sabit (23.0°C). Su hatlarını hazırlaması için kümes sorumlusuna anında hatırlatma göndereyim mi?",
            "id" to "⏰ Peringatan Proaktif: Jadwal vaksinasi / tagihan rutin berikutnya sudah dekat, dan suhu kandang stabil (23.0°C). Kirim pengingat instan ke pengawas kandang untuk menyiapkan jalur air?",
            "ur" to "⏰ پیشگی تنبیہ: اگلی ویکسینیشن / دورانیہ بل کا وقت قریب ہے اور شیڈ کا درجہ حرارت مستحکم (23.0°C) ہے۔ کیا میں نگران کو پانی کی لائنیں تیار کرنے کے لیے فوری یاد دہانی بھیج دوں؟",
            "sw" to "⏰ Tahadhari ya Mapema: Muda wa chanjo / ankara inayofuata umekaribia na joto la banda ni tulivu (23.0°C). Nitume ukumbusho wa haraka kwa msimamizi kuandaa mabomba ya maji?",
            "ru" to "⏰ Проактивное уведомление: Приближается срок вакцинации / периодического платежа, температура в птичнике стабильна (23.0°C). Отправить мгновенное напоминание бригадиру подготовить линии поения?",
            "zh" to "⏰ 主动提醒：即将到达免疫/周期账单节点，当前鸡舍温度稳定 (23.0°C)。是否立即向鸡舍主管发送准备饮水线的通知？",
