        "account_delete_dialog_body" to mapOf(
            "ar" to "هل أنت متأكد من رغبتك في حذف حسابك نهائياً؟ سيتم مسح وثيقة حسابك وجميع عنابرك وتقاريرك اليومية وفواتيرك السحابية والمحلية نهائياً ولا يمكن التراجع عن هذا الإجراء.",
            "fr" to "Voulez-vous vraiment supprimer votre compte ? Votre profil, vos bâtiments, vos rapports quotidiens et vos factures cloud/locales seront effacés définitivement.",
            "en" to "Are you sure you want to permanently delete your account? Your profile, barns, daily reports, and invoices in cloud and local storage will be permanently erased.",
            "es" to "¿Está seguro de eliminar permanentemente su cuenta? Su perfil, galpones, informes diarios y facturas en la nube y locales se borrarán de forma irreversible.",
