            "hi" to "क्या आप वाकई अपना खाता स्थायी रूप से हटाना चाहते हैं? आपकी प्रोफ़ाइल, शेड, दैनिक रिपोर्ट और क्लाउड/लोकल चालान स्थायी रूप से मिटा दिए जाएंगे।",
            "tr" to "Hesabınızı kalıcı olarak silmek istediğinizden emin misiniz? Profiliniz, kümesleriniz, günlük raporlarınız ve bulut/yerel faturalarınız kalıcı olarak silinecektir.",
            "id" to "Yakin ingin menghapus akun Anda secara permanen? Profil, kandang, laporan harian, dan faktur di cloud serta lokal akan dihapus secara permanen.",
            "ur" to "کیا آپ واقعی اپنا اکاؤنٹ مستقل طور پر حذف کرنا چاہتے ہیں؟ آپ کی پروفائل، شیڈز، روزانہ کی رپورٹس اور کلاؤڈ و مقامی بل مستقل مٹ جائیں گے۔",
            "sw" to "Una uhakika unataka kufuta akaunti yako kabisa? Wasifu, mabanda, ripoti za kila siku, na ankara kwenye wingu na simu zitafutwa kabisa.",
