            "hi" to "IQ Notebook केवल पोल्ट्री चक्र के खर्च, पक्षियों के वजन और लाभ की गणना के लिए एक स्मार्ट डिजिटल रजिस्टर है।",
            "tr" to "IQ Notebook, yalnızca kanatlı kümes giderlerini, ağırlıklarını ve kârını takip eden akıllı dijital bir defterdir.",
            "id" to "IQ Notebook adalah buku catatan digital untuk mendokumentasikan biaya, bobot, dan laba siklus unggas.",
            "ur" to "IQ Notebook صرف پولٹری سائیکل کے اخراجات، وزن اور منافع کے حساب کتاب کے لیے ایک اسمارٹ ڈیجیٹل رجسٹر ہے۔",
            "sw" to "IQ Notebook ni daftari la kidijitali la kurekodi na kukokotoa gharama, uzito na faida ya mzunguko wa kuku.",
            "ru" to "IQ Notebook — цифровой журнал для учета расходов, веса птицы и прибыли птицеводческого цикла.",
            "zh" to "IQ Notebook 是一款专门用于记录和计算肉鸡养殖周期支出、体重和利润的智能数字账本。",
            "de" to "IQ Notebook ist ein digitales Betriebsbuch zur Dokumentation und Berechnung von Stallkosten, Gewichten und Erträgen.",
            "it" to "IQ Notebook è un registro digitale per documentare e calcolare spese, pesi e profitti del ciclo avicolo."
        ),
