        "privacy_sec2_body" to mapOf(
            "ar" to "البريد الإلكتروني ومعرّف الحساب (عبر Google Sign-In) للمزامنة السحابية بين أجهزة المالك والعمال، مع إمكانية حذف الحساب والبيانات نهائياً في أي وقت من الإعدادات.",
            "fr" to "Votre e-mail et UID (via Google Sign-In) servent uniquement à la synchronisation cloud entre propriétaire et équipe. Vous pouvez tout supprimer à tout moment dans Paramètres.",
            "en" to "Your email and account UID (via Google Sign-In) are used strictly for real-time cloud synchronization between owner and team devices. You can permanently delete your account and data anytime from Settings.",
            "es" to "Su correo y UID (mediante Google Sign-In) se usan solo para la sincronización en la nube entre propietario y equipo. Puede eliminar su cuenta en Ajustes en cualquier momento.",
            "pt" to "Seu e-mail e UID (via Google Sign-In) são usados apenas para sincronização na nuvem entre proprietário e equipe. Você pode excluir tudo nas Configurações a qualquer momento.",
            "hi" to "आपका ईमेल और UID (Google Sign-In) केवल मालिक और टीम के बीच क्लाउड सिंक के लिए उपयोग होता है। आप सेटिंग्स से कभी भी अपना खाता हटा सकते हैं।",
            "tr" to "E-postanız ve UID (Google Sign-In) yalnızca sahip ile ekip senkronizasyonu içindir. Ayarlar'dan hesabınızı istediğiniz zaman kalıcı olarak silebilirsiniz.",
            "id" to "Email dan UID Anda (via Google Sign-In) hanya untuk sinkronisasi cloud antara pemilik dan tim. Anda dapat menghapus akun kapan saja di Pengaturan.",
            "ur" to "آپ کا ای میل اور UID (Google Sign-In کے ذریعے) صرف مالک اور ٹیم کے درمیان کلاؤڈ سنک کے لیے استعمال ہوتا ہے۔ آپ ترتیبات سے کبھی بھی اکاؤنٹ حذف کر سکتے ہیں۔",
            "sw" to "Barua pepe na UID (kupitia Google Sign-In) hutumika kwa usawazishaji wa wingu kati ya mmiliki na timu. Unaweza kufuta akaunti wakati wowote kwenye Mipangilio.",
            "ru" to "Ваш email и UID (через Google Sign-In) используются только для облачной синхронизации команды. Вы можете удалить аккаунт в Настройках в любое время.",
            "zh" to "您的邮箱和账号 UID（通过 Google 登录）仅用于农场主与团队设备间的云端同步。您可随时在设置中永久删除账号和数据。",
            "de" to "E-Mail und UID (über Google Sign-In) dienen nur der Cloud-Synchronisation des Teams. Sie können Ihr Konto jederzeit in den Einstellungen löschen.",
            "it" to "Email e UID (tramite Google Sign-In) servono solo per la sincronizzazione cloud del team. Puoi eliminare tutto dalle Impostazioni in qualsiasi momento."
        ),
