        "privacy_sec3_body" to mapOf(
            "ar" to "يستخدم التطبيق الكاميرا حصرياً لمسح رمز الاستجابة السريعة (QR Code) عند ربط جهاز العامل أو الطبيب بالعنبر، ولا يقوم بالتقاط أو تخزين أو رفع أي صور أو مقاطع فيديو شخصية.",
            "fr" to "La caméra sert exclusivement à scanner les codes QR d'invitation de l'équipe. Aucune photo ni vidéo personnelle n'est capturée, stockée ou envoyée.",
            "en" to "Camera access is used exclusively to scan team/barn QR join codes. The app never captures, stores, or uploads personal photos or videos.",
            "es" to "La cámara se usa exclusivamente para escanear códigos QR de invitación del equipo. Nunca captura, guarda ni sube fotos o videos personales.",
            "pt" to "A câmera é usada apenas para ler códigos QR de convite da equipe. Nunca captura, armazena ou envia fotos ou vídeos pessoais.",
            "hi" to "कैमरा केवल टीम/शेड के QR कोड स्कैन करने के लिए उपयोग होता है। ऐप कोई व्यक्तिगत फ़ोटो या वीडियो नहीं सहेजता या अपलोड करता।",
            "tr" to "Kamera yalnızca ekip QR davet kodlarını taramak için kullanılır; kişisel fotoğraf veya video kaydetmez ya da yüklemez.",
            "id" to "Kamera hanya digunakan untuk memindai kode QR undangan tim. Aplikasi tidak pernah menyimpan atau mengunggah foto/video pribadi.",
            "ur" to "کیمرہ صرف ٹیم کے QR کوڈ اسکین کرنے کے لیے استعمال ہوتا ہے؛ کوئی ذاتی تصویر یا ویڈیو محفوظ یا اپ لوڈ نہیں کی جاتی۔",
            "sw" to "Kamera hutumika kusoma misimbo ya QR ya timu pekee. Programu haichukui wala kupakia picha au video binafsi.",
            "ru" to "Камера используется только для сканирования QR-кодов приглашения команды. Личные фото и видео не сохраняются и не отправляются.",
            "zh" to "相机权限仅用于扫描团队/鸡舍邀请二维码，绝不拍摄、保存或上传任何个人照片或视频。",
            "de" to "Die Kamera wird ausschließlich zum Scannen von Team-QR-Codes verwendet. Es werden keine privaten Fotos oder Videos gespeichert.",
