        "privacy_sec4_body" to mapOf(
            "ar" to "المعلومات الواردة في تبويب \"📖 الكتاب\" والمستشار الذكي مستندة إلى المراجع القياسية لسلالة التسمين (Ross 308) وهي للإرشاد المزرعي فقط ولا تغني عن الفحص الميداني أو وصفة طبيب بيطري مرخص.",
            "fr" to "Les guides de l'onglet « 📖 Livre » et de l'assistant IA s'appuient sur les manuels Ross 308 à titre indicatif uniquement et ne remplacent pas un vétérinaire agréé.",
            "en" to "Guidelines in \"📖 Book\" and AI insights are adapted from Ross 308 management handbooks for farm reference only and do not replace inspection by a licensed veterinarian.",
            "es" to "La guía de \"📖 Libro\" y el asistente IA se basan en manuales Ross 308 solo con fines orientativos y no sustituyen a un veterinario autorizado.",
            "pt" to "As orientações em \"📖 Livro\" e da IA são baseadas nos manuais Ross 308 apenas para referência e não substituem um médico veterinário habilitado.",
            "hi" to "\"📖 पुस्तक\" और AI सुझाव केवल Ross 308 संदर्भ के लिए हैं और लाइसेंस प्राप्त पशु चिकित्सक की जांच का स्थान नहीं लेते।",
            "tr" to "\"📖 Kitap\" ve YZ rehberleri yalnızca Ross 308 referans amaçlıdır; lisanslı veteriner hekim muayenesinin yerini almaz.",
            "id" to "Panduan di \"📖 Buku\" dan saran AI merujuk pada standar Ross 308 hanya untuk referensi dan tidak menggantikan dokter hewan berlisensi.",
            "ur" to "\"📖 کتاب\" اور اے آئی مشورے صرف Ross 308 رہنمائی کے لیے ہیں اور لائسنس یافتہ ویٹرنری ڈاکٹر کے معائنے کا نعم البدل نہیں ہیں۔",
            "sw" to "Miongozo ya \"📖 Kitabu\" na AI inatokana na Ross 308 kwa marejeo tu na haichukui nafasi ya daktari wa mifugo aliyeidhinishwa.",
            "ru" to "Материалы в разделе «📖 Книга» и советы ИИ основаны на стандартах Ross 308 только для справки и не заменяют осмотр ветеринара.",
            "zh" to "“📖 手册”与 AI 建议基于 Ross 308 养殖标准，仅供参考，不能替代执业兽医的现场检查和处方。",
            "de" to "Hinweise in „📖 Buch“ und KI basieren auf Ross 308 Standards und ersetzen keine Untersuchung durch einen zugelassenen Tierarzt.",
            "it" to "Le linee guida in \"📖 Libro\" e i consigli IA si basano sui manuali Ross 308 solo a scopo informativo e non sostituiscono un veterinario abilitato."
        ),
        "privacy_sec5_title" to mapOf(
            "ar" to "5. الذكاء الاصطناعي (Gemini AI) وخدمة الطقس (Open-Meteo) ☁️",
            "fr" to "5. Analyse IA (Gemini AI) & Météo (Open-Meteo) ☁️",
            "en" to "5. Cloud AI (Firebase Gemini) & Weather (Open-Meteo) ☁️",
