            "hi" to "5. क्लाउड AI (Gemini) और मौसम सेवा (Open-Meteo) ☁️",
            "tr" to "5. Bulut Yapay Zeka (Gemini) ve Hava Durumu (Open-Meteo) ☁️",
            "id" to "5. Layanan AI (Firebase Gemini) & Cuaca (Open-Meteo) ☁️",
