            "ru" to "5. Облачный ИИ (Gemini) и Погода (Open-Meteo) ☁️",
            "zh" to "5. 云端 AI（Firebase Gemini）与天气服务（Open-Meteo）☁️",
            "de" to "5. Cloud-KI (Firebase Gemini) & Wetter (Open-Meteo) ☁️",
            "it" to "5. IA Cloud (Firebase Gemini) e Meteo (Open-Meteo) ☁️"
        ),
        "privacy_sec5_body" to mapOf(
            "ar" to "عند استخدام المستشار الذكي، تُعالج استفساراتك وسياق العنبر عبر Firebase AI (Gemini) لتوليد الإرشادات فقط. وعند تفعيل الطقس الاختياري، تُرسل المدينة أو الإحداثيات المختارة يدوياً إلى Open-Meteo لجلب حالة الطقس، دون أي تتبع GPS بالخلفية أو مشاركة مع أي شبكات إعلانية.",
            "fr" to "Lorsque vous interrogez l'assistant IA, vos questions sont traitées par Firebase AI (Gemini) uniquement pour générer des conseils. Pour la météo, la ville choisie manuellement est envoyée à Open-Meteo sans suivi GPS ni partage publicitaire.",
            "en" to "When using AI Vet, your prompts and relevant barn context are sent to Firebase AI (Gemini) solely to generate guidance. When enabling outdoor weather, your manually chosen locality/coordinates are sent to Open-Meteo for weather forecasts — with zero background GPS tracking and zero ad-network data sharing.",
            "es" to "Al usar el asistente IA, sus consultas se procesan mediante Firebase AI (Gemini) solo para generar orientación. La localidad elegida para el clima se consulta en Open-Meteo sin rastreo GPS ni redes publicitarias.",
            "pt" to "Ao usar o assistente de IA, suas perguntas são enviadas ao Firebase AI (Gemini) apenas para gerar orientações. A localidade escolhida para o clima é consultada no Open-Meteo, sem rastreamento GPS ou compartilhamento com anúncios.",
            "hi" to "AI सलाह का उपयोग करते समय आपके प्रश्न केवल मार्गदर्शन के लिए Firebase AI (Gemini) को भेजे जाते हैं। मौसम के लिए चुना गया स्थान Open-Meteo को भेजा जाता है — बिना किसी GPS ट्रैकिंग या विज्ञापन साझा करने के।",
            "tr" to "YZ danışmanını kullandığınızda sorularınız yalnızca rehberlik için Firebase AI (Gemini)'a gönderilir. Hava durumu için seçilen konum Open-Meteo'ya iletilir; arka plan GPS takibi veya reklam paylaşımı yoktur.",
            "id" to "Saat memakai Konsultan AI, pertanyaan dikirim ke Firebase AI (Gemini) hanya untuk panduan. Lokasi yang Anda pilih untuk cuaca dikirim ke Open-Meteo tanpa pelacakan GPS atau jaringan iklan.",
            "ur" to "اے آئی مشیر استعمال کرتے وقت آپ کے سوالات صرف رہنمائی کے لیے Firebase AI (Gemini) کو بھیجے جاتے ہیں۔ موسم کے لیے منتخب شہر Open-Meteo کو بھیجا جاتا ہے، بغیر کسی GPS ٹریکنگ یا اشتہاری اشتراک کے۔",
            "sw" to "Unapotumia mshauri wa AI, maswali hutumwa Firebase AI (Gemini) kwa ushauri pekee. Mji uliochagua kwa hali ya hewa hutumwa Open-Meteo bila ufuatiliaji wa GPS au matangazo.",
            "ru" to "При обращении к ИИ запросы отправляются в Firebase AI (Gemini) только для рекомендаций. Выбранный вами город передается в Open-Meteo для прогноза погоды — без фонового GPS-трекинга и передачи рекламным сетям.",
            "zh" to "使用 AI 助手时，您的提问及鸡舍上下文仅发送至 Firebase AI (Gemini) 生成建议；开启天气时，仅将您手动选择的城市发送至 Open-Meteo 获取预报，绝无后台 GPS 追踪或广告共享。",
            "de" to "Bei Nutzung des KI-Beraters werden Ihre Anfragen nur zur Beratung an Firebase AI (Gemini) gesendet. Für das Wetter wird Ihr manuell gewählter Ort an Open-Meteo gesendet — ohne GPS-Tracking oder Werbenetzwerke.",
            "it" to "Quando usi l'assistente IA, le richieste vengono elaborate da Firebase AI (Gemini) solo per generare consigli. La località scelta per il meteo viene inviata a Open-Meteo senza tracciamento GPS né condivisione pubblicitaria."
        ),
